#!/usr/bin/env python3
"""
Build ME4.json — English translation file for M4 (Ninja Spinner).

Card translations sourced from PokeBeach (Jake C. translations).
This script outputs a structured JSON file matching the ME3.json schema,
with added abilities and attack effects.
"""
import json, pathlib

DATA_DIR = pathlib.Path(__file__).resolve().parent.parent / "data"
OUT = DATA_DIR / "ME4.json"
IMAGES_PATH = DATA_DIR / "me4_images.json"
M4_PATH = DATA_DIR / "M4.json"

# Optional sidecar of official EN images scraped from asia.pokemon-card.com.
# Generated by scripts/scrape_me4_images.py. Image lookup is by card NAME
# (not collector number), because PokeBeach numbering diverges from the
# official EN print starting at position 48 (Mega Gallade ex inserted).
# For names with multiple occurrences in ME4.json (e.g. four "Deoxys"),
# Nth ME4 occurrence maps to Nth asia occurrence.
_IMAGES_BY_NAME: dict = {}
if IMAGES_PATH.exists():
    _sidecar = json.loads(IMAGES_PATH.read_text())
    for entry in _sidecar.get("ordered", []):
        _IMAGES_BY_NAME.setdefault(entry["name"], []).append(entry["image"])

_NAME_OCCURRENCE: dict = {}

# JP illustrator backfill — needed for matcher disambiguation when a single
# Pokemon has multiple cards with the same dexId (e.g. four Deoxys formes
# at M4-031..034). PokeBeach text doesn't include illustrator, but the JP
# M4 set does. ME4 collector numbers map 1:1 to M4 collector numbers
# (PokeBeach pre-release alignment), so the lookup is by zero-padded number.
_M4_ILLUSTRATORS: dict = {}
if M4_PATH.exists():
    _m4 = json.loads(M4_PATH.read_text())
    for k, c in _m4.get("cards", {}).items():
        if c.get("illustrator"):
            _M4_ILLUSTRATORS[k] = c["illustrator"]

SET_META = {
    "id": "ME4",
    "name": {"en": "Chaos Rising"},
    "serie": "Mega Evolution",
    "releaseDate": {"en": "2026-05-22"},
    "jpSetId": "M4",
}

def card(num, name, **kw):
    """Helper to build a card dict with defaults."""
    occ = _NAME_OCCURRENCE.get(name, 0)
    matches = _IMAGES_BY_NAME.get(name, [])
    img = matches[occ] if occ < len(matches) else None
    _NAME_OCCURRENCE[name] = occ + 1
    key = f"{num:03d}"
    c = {"name": name, "id": f"ME4-{key}", "set": {"id": "ME4", "name": "Chaos Rising"}, "image": img}
    illus = _M4_ILLUSTRATORS.get(key)
    if illus:
        c["illustrator"] = illus
    c.update(kw)
    return (key, c)

def pokemon(num, name, hp, types, stage, retreat, dexId, rarity, attacks, abilities=None, weakness=None, resistance=None):
    kw = {"category": "Pokemon", "hp": hp, "types": types, "stage": stage, "retreat": retreat, "dexId": dexId, "rarity": rarity, "attacks": attacks}
    if abilities:
        kw["abilities"] = abilities
    if weakness:
        kw["weakness"] = weakness
    if resistance:
        kw["resistance"] = resistance
    return card(num, name, **kw)

def trainer(num, name, rarity, effect, subcategory=None):
    kw = {"category": "Trainer", "rarity": rarity, "effect": effect}
    if subcategory:
        kw["subcategory"] = subcategory
    return card(num, name, **kw)

def energy(num, name, rarity, effect):
    return card(num, name, category="Energy", rarity=rarity, effect=effect)

