# --- Build and write ---
data = {**SET_META, "cards": cards}

# Coverage report — surfaces names that didn't match the asia sidecar.
total = len(data["cards"])
with_image = sum(1 for c in data["cards"].values() if c.get("image"))
without = [c["name"] for c in data["cards"].values() if not c.get("image")]
print(f"Image coverage: {with_image}/{total} cards have official EN images")
if without:
    print(f"  No image for {len(without)} cards (PokeBeach naming differs from asia):")
    for name in without:
        print(f"    - {name}")

OUT.write_text(json.dumps(data, indent=2, ensure_ascii=False))
print(f"Wrote {len(cards)} cards to {OUT}")
